-- Generated by drizzle-kit generate --custom. 0095 is immutable and already applied.
-- Feature evidence belongs to a clause, not to the whole paragraph. Unknown stays unknown.
CREATE OR REPLACE FUNCTION public_bot.feature(d jsonb,n text,s text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public_bot AS $$
DECLARE line text; whole text; clause text; st text; found text; evidence text; mentions integer; in_condo boolean; in_private boolean; direct_private boolean;
BEGIN
 IF n NOT IN ('piscina','churrasqueira','sala','cozinha') OR s NOT IN ('private','condominium') THEN RETURN jsonb_build_object('state','unknown','evidence',NULL); END IF;
 FOR line IN SELECT value FROM jsonb_array_elements_text(coalesce(d->'features','[]')) UNION ALL SELECT regexp_split_to_table(coalesce(d->>'description',''),'[.;\n]') LOOP
  whole:=public_bot.norm(line);
  IF whole !~ ('\m'||n||'\M') OR whole ~ 'ignore|instrucoes|system|prompt|senha|token|proprietario|cpf|comissao' THEN CONTINUE; END IF;
  SELECT count(*) INTO mentions FROM regexp_matches(whole,'\m(piscina|churrasqueira|sala|cozinha)\M','g');
  FOR clause IN SELECT regexp_split_to_table(whole,'(,[[:space:]]*|,?[[:space:]]+(e|mas)[[:space:]]+)(?=((com|sem|uma?|nao ha|nao possui|nao tem)[[:space:]]+)*(piscina|churrasqueira|sala|cozinha)\M)') LOOP
   IF clause !~ ('\m'||n||'\M') OR clause ~ 'espaco para|possibilidade|projeto|construir|pode (ter|instalar)|futura|previsao|preparacao|nao informad|nao confirmad|sem informacao|nao (ha|tem|possui) (informacao|indicacao|confirmacao)' THEN CONTINUE; END IF;
   direct_private:=clause ~ ('\m'||n||'[[:space:]]+(privativ[ao]|particular)\M');
   in_condo:=clause ~ 'condominio|condominial|compartilhad|coletiv';
   in_private:=clause ~ 'privativ[ao]|particular|do imovel|da casa';
   -- “Casa em condomínio com piscina privativa” explicitly locates this pool at the property.
   IF direct_private THEN in_condo:=false; in_private:=true; END IF;
   IF in_condo AND in_private THEN CONTINUE; END IF;
   IF NOT in_condo AND NOT in_private AND whole ~ 'condominio|condominial|compartilhad|coletiv' AND mentions>1 THEN CONTINUE; END IF;
   IF (s='condominium') IS DISTINCT FROM in_condo THEN CONTINUE; END IF;
   st:=NULL;
   IF clause ~ ('(sem|nao (tem|ha|possui|inclui|conta com|dispoe de)) (uma? )?'||n||'\M') OR clause ~ ('\m'||n||' (inexistente|ausente|nao (existe|disponivel|informada))\M') THEN st:='absent';
   ELSIF (d->'features') ? line OR clause ~ ('(com|possui|tem|conta com|dispoe de|oferece) ([[:alnum:]_]+ ){0,2}'||n||'\M|\m'||n||' (privativa|existente|no condominio)') THEN st:='present'; END IF;
   IF st IS NOT NULL THEN
    IF found IS NOT NULL AND found<>st THEN RETURN jsonb_build_object('state','unknown','evidence',NULL); END IF;
    found:=st; evidence:=left(btrim(line),200);
   END IF;
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('state',coalesce(found,'unknown'),'evidence',evidence);
END $$;
