-- A stale first batch must not hide the valid 31st (or later) match. Query all matching public
-- identifiers, ordered deterministically, and revalidate bounded batches until 30 survive.
-- No catalog descriptions are sent to the browser or model by this internal iteration.
CREATE OR REPLACE FUNCTION public_bot.candidates(b text,f jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
DECLARE all_ids uuid[]; cursor_pos integer:=1; verified jsonb:='[]'; result jsonb;
BEGIN
 IF b NOT IN ('cordial','morar') OR NOT public_bot.valid_filters(f) THEN RETURN '[]'::jsonb; END IF;
 WITH matches AS (SELECT d.public_id,
  (SELECT count(*) FROM jsonb_array_elements(coalesce(f->'features','[]')) x WHERE coalesce((x->>'required')::boolean,true)=false AND public_bot.feature(d.document,x->>'name',x->>'scope')->>'state' IS DISTINCT FROM x->>'state') AS differences
 FROM public_bot.search_documents d WHERE d.brand=b
 AND (f->>'operation' IS NULL OR d.operation=f->>'operation') AND (f->>'type' IS NULL OR d.type=public_bot.norm(f->>'type')) AND (f->>'city' IS NULL OR d.city=public_bot.norm(f->>'city')) AND (f->>'district' IS NULL OR d.district=public_bot.norm(f->>'district'))
 AND (f->>'reference' IS NULL OR public_bot.norm(d.document->>'reference')=public_bot.norm(f->>'reference')) AND (f->>'stage' IS NULL OR public_bot.norm(d.document->>'stage')=public_bot.norm(f->>'stage'))
 AND (f->'budget' IS NULL OR f->'budget'='null'::jsonb OR d.document->>'priceMode'='fixo' AND public_bot.range_match(d.price,f->'budget'))
 AND public_bot.count_match((d.document->>'bedrooms')::numeric,f->'bedrooms') AND public_bot.count_match((d.document->>'bathrooms')::numeric,f->'bathrooms') AND public_bot.count_match((d.document->>'suites')::numeric,f->'suites') AND public_bot.count_match((d.document->>'parking')::numeric,f->'parking')
 AND (f->>'furnished' IS NULL OR d.document->>'furnished'=f->>'furnished') AND (f->>'exchange' IS NULL OR d.document->>'exchange'=f->>'exchange') AND (f->>'financing' IS NULL OR d.document->>'financing'=f->>'financing')
 AND (f->'area' IS NULL OR f->'area'='null'::jsonb OR public_bot.range_match((d.document->'areas'->>(f->'area'->>'kind'))::numeric,f->'area'->'range'))
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(f->'features','[]')) x WHERE coalesce((x->>'required')::boolean,true) AND public_bot.feature(d.document,x->>'name',x->>'scope')->>'state' IS DISTINCT FROM x->>'state'))
 SELECT coalesce(array_agg(public_id ORDER BY differences,public_id),'{}'::uuid[]) INTO all_ids FROM matches;
 WHILE cursor_pos<=cardinality(all_ids) AND jsonb_array_length(verified)<30 LOOP
  verified:=verified||public_bot.resolve(b,all_ids[cursor_pos:(cursor_pos+29)]);
  cursor_pos:=cursor_pos+30;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY ordinality),'[]'::jsonb) INTO result FROM jsonb_array_elements(verified) WITH ORDINALITY WHERE ordinality<=30;
 RETURN result;
END $$;

