-- Stable hourly key independent of the SQL connection timezone; BRL labels use pt-BR grouping.
CREATE OR REPLACE FUNCTION public_bot.suggestion_set(b text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
DECLARE c public_bot.configuration_data; h timestamptz:=date_trunc('hour',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'; ver text; pool jsonb; output jsonb:='[]'; row record; suggestion jsonb;
BEGIN
 SELECT * INTO c FROM public_bot.configuration_data WHERE brand=b;
 IF NOT coalesce(c.enabled,false) THEN RETURN jsonb_build_object('version','unavailable','suggestions','[]'::jsonb); END IF;
 SELECT md5(coalesce(string_agg(source_version,',' ORDER BY public_id),'')) INTO ver FROM public_bot.search_documents WHERE brand=b;
 SELECT suggestions INTO pool FROM public_bot.suggestion_sets WHERE brand=b AND hour=h AND catalog_version=ver;
 IF pool IS NULL THEN
  WITH choices AS (
   SELECT DISTINCT 'type' AS category, jsonb_build_object('operation',operation,'type',document->>'type') AS patch,
    (document->>'type')||CASE WHEN operation='aluguel' THEN ' para alugar' ELSE ' para comprar' END AS label
    FROM public_bot.search_documents WHERE brand=b AND document->>'type' IS NOT NULL
   UNION ALL SELECT DISTINCT 'district',jsonb_build_object('operation',operation,'city',document->>'city','district',document->>'district'),(document->>'district')||' · '||(document->>'city')||CASE WHEN operation='aluguel' THEN ' · aluguel' ELSE ' · compra' END
    FROM public_bot.search_documents WHERE brand=b AND document->>'city' IS NOT NULL AND document->>'district' IS NOT NULL
   UNION ALL SELECT DISTINCT 'budget',jsonb_build_object('operation',operation,'budget',jsonb_build_object('min',NULL,'max',jsonb_build_object('value',ceil(price/CASE WHEN operation='aluguel' THEN 500 ELSE 100000 END)*CASE WHEN operation='aluguel' THEN 500 ELSE 100000 END,'inclusive',true))),
    CASE WHEN operation='aluguel' THEN 'Aluguel até R$ ' ELSE 'Compra até R$ ' END||replace(to_char(ceil(price/CASE WHEN operation='aluguel' THEN 500 ELSE 100000 END)*CASE WHEN operation='aluguel' THEN 500 ELSE 100000 END,'FM999,999,999,990'),',','.')||CASE WHEN operation='aluguel' THEN '/mês' ELSE '' END
    FROM public_bot.search_documents WHERE brand=b AND document->>'priceMode'='fixo' AND price>0
   UNION ALL SELECT DISTINCT 'feature',jsonb_build_object('operation',d.operation,'features',jsonb_build_array(jsonb_build_object('name',f.name,'scope',f.scope,'state','present','required',true))),
    CASE WHEN d.operation='aluguel' THEN 'Aluguel com ' ELSE 'Compra com ' END||f.name||CASE WHEN f.scope='condominium' THEN ' no condomínio' ELSE '' END
    FROM public_bot.search_features f JOIN public_bot.search_documents d ON d.brand=f.brand AND d.public_id=f.public_id AND d.source_version=f.source_version
    WHERE d.brand=b AND f.state='present' AND f.name IN ('piscina','churrasqueira')
  ), distinct_choices AS (
   SELECT DISTINCT category,patch,left(label,120) AS label FROM choices WHERE length(label)<=120
  ), named AS (
   SELECT *,category||':'||left(md5(patch::text),16) AS id FROM distinct_choices
  ), scored AS (
   SELECT n.*,CASE WHEN c.trends AND (SELECT count(DISTINCT e.session_id) FROM public_bot.suggestion_contributions e WHERE e.brand=b AND e.suggestion_id=n.id AND e.hour>now()-interval '24 hours')>=5 THEN
    coalesce((SELECT sum((s.searches*c.trend_search_weight+s.opens*c.trend_open_weight+s.whatsapp*c.trend_whatsapp_weight)*power(0.5,extract(epoch FROM now()-s.hour)/3600/c.trend_half_life_hours))/greatest(sum(s.impressions),1) FROM public_bot.suggestion_stats s WHERE s.brand=b AND s.suggestion_id=n.id AND s.hour>now()-interval '24 hours'),0)
    ELSE 0 END AS trend FROM named n
  ), diverse AS (
   SELECT *,row_number() OVER(PARTITION BY category ORDER BY trend DESC,md5(h::text||id),id) AS category_rank FROM scored
  ) SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'label',label,'patch',patch) ORDER BY category_rank,trend DESC,md5(h::text||id)),'[]') INTO pool FROM (SELECT * FROM diverse ORDER BY category_rank,trend DESC,md5(h::text||id) LIMIT 20) x;
  INSERT INTO public_bot.suggestion_sets(brand,hour,catalog_version,suggestions) VALUES(b,h,ver,pool) ON CONFLICT DO NOTHING;
 END IF;
 -- Cached criteria are not proof of current availability. Revalidate the actual search every serve.
 FOR suggestion IN SELECT value FROM jsonb_array_elements(pool) LOOP
  IF jsonb_array_length(public_bot.candidates(b,suggestion->'patch'))>0 THEN output:=output||jsonb_build_array(suggestion); END IF;
  EXIT WHEN jsonb_array_length(output)>=4;
 END LOOP;
 RETURN jsonb_build_object('version',to_char(h AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24')||':'||ver,'suggestions',output);
END $$;

