-- Reopening a panel never resets the global IP quota; report only the exhausted state, not a counter.
CREATE OR REPLACE FUNCTION public_bot.open_session(b text,token_hash text,ip_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions; n integer;
BEGIN
 IF coalesce(b,'') NOT IN ('cordial','morar') OR coalesce(token_hash,'') !~ '^[a-f0-9]{64}$' OR coalesce(ip_key,'') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'invalid' USING ERRCODE='22023'; END IF;
 INSERT INTO public_bot.open_limits VALUES(ip_key,now(),1) ON CONFLICT ON CONSTRAINT open_limits_pkey DO UPDATE SET attempts=CASE WHEN open_limits.window_at<now()-interval '1 minute' THEN 1 ELSE open_limits.attempts+1 END, window_at=CASE WHEN open_limits.window_at<now()-interval '1 minute' THEN now() ELSE open_limits.window_at END RETURNING attempts INTO n;
 IF n>10 THEN RETURN '{"code":"burst"}'; END IF;
 DELETE FROM public_bot.sessions WHERE sessions.brand=b AND sessions.token_hash=token_hash AND (expires_at<now() OR created_at<now()-interval '7 days');
 INSERT INTO public_bot.sessions(brand,token_hash,draft) VALUES(b,token_hash,public_bot.empty_draft()) ON CONFLICT ON CONSTRAINT sessions_brand_token_hash_key DO UPDATE SET last_used=now(),expires_at=least(sessions.created_at+interval '7 days',now()+interval '24 hours') RETURNING * INTO s;
 RETURN jsonb_build_object('id',s.id,'draft',s.draft,'exhausted',coalesce((SELECT q.accepted>=25 FROM public_bot.daily_quotas q WHERE q.ip_key=ip_key AND q.local_day=(now() AT TIME ZONE 'America/Sao_Paulo')::date),false),'turns',coalesce((SELECT jsonb_agg(jsonb_build_object('requestId',t.request_id,'answer',t.result->>'answer','ids',t.ids) ORDER BY t.created_at) FROM (SELECT * FROM public_bot.turns r WHERE r.session_id=s.id AND r.state='completed' ORDER BY r.created_at DESC LIMIT 25) t),'[]'));
END $$;
