-- A transcript arriving after its reservation lease cannot be reported as a counted success.
CREATE OR REPLACE FUNCTION public_bot.finish_voice(b text,token_hash text,request_id uuid,ok boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions; v public_bot.voice_requests;
BEGIN
 SELECT * INTO s FROM public_bot.sessions x WHERE x.brand=b AND x.token_hash=token_hash FOR UPDATE;
 SELECT * INTO v FROM public_bot.voice_requests x WHERE x.session_id=s.id AND x.request_id=request_id FOR UPDATE;
 IF v.state IS DISTINCT FROM 'accepted' THEN RETURN false; END IF;
 UPDATE public_bot.voice_requests x SET state=CASE WHEN ok AND v.lease_until>=now() THEN 'completed' ELSE 'failed' END WHERE x.session_id=s.id AND x.request_id=request_id;
 UPDATE public_bot.daily_quotas x SET voice_reserved=greatest(0,x.voice_reserved-1),voices=x.voices+CASE WHEN ok AND v.lease_until>=now() THEN 1 ELSE 0 END WHERE x.ip_key=v.ip_key AND x.local_day=v.local_day;
 UPDATE public_bot.sessions SET active_request=NULL,lease_until=NULL WHERE id=s.id AND active_request=request_id;
 RETURN NOT ok OR v.lease_until>=now();
END $$;
--> statement-breakpoint
-- Recompute only derived public evidence; commercial fields and publication decisions are untouched.
UPDATE public_bot.search_features f SET state=public_bot.feature(d.document,f.name,f.scope)->>'state',evidence=public_bot.feature(d.document,f.name,f.scope)->>'evidence'
FROM public_bot.search_documents d WHERE d.brand=f.brand AND d.public_id=f.public_id AND d.source_version=f.source_version;
DELETE FROM public_bot.suggestion_sets;
-- CREATE OR REPLACE preserves 0095 ownership and ACL; assert it before exposing updated schema.
DO $$ BEGIN
 IF has_function_privilege('anon','public_bot.candidates(text,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public_bot.candidates(text,jsonb)','EXECUTE') OR has_schema_privilege('public_bot_runtime','public','USAGE') THEN RAISE EXCEPTION 'public bot privilege boundary changed'; END IF;
END $$;
NOTIFY pgrst,'reload schema';
